import pytest

from minisheet.refs import Ref, parse_range, parse_ref, to_a1


# B§1 table rows
def test_parse_ref_b12():
    assert parse_ref("B12") == Ref(1, 11, False, False)


def test_parse_ref_absolute_lowercase_max():
    assert parse_ref("$zz$9999") == Ref(701, 9998, True, True)


def test_parse_range_mixed_flags():
    assert parse_range("$C3:A$1") == (Ref(0, 0, False, True), Ref(2, 2, True, False))


def test_to_a1_absolute_col():
    assert to_a1(Ref(26, 0, True, False)) == "$AA1"


def test_parse_ref_a0_rejected():
    with pytest.raises(ValueError):
        parse_ref("A0")


def test_parse_ref_aaa1_rejected():
    with pytest.raises(ValueError):
        parse_ref("AAA1")


# Review Focus
def test_a01_rejected():
    with pytest.raises(ValueError):
        parse_ref("A01")


def test_range_bare_cell():
    with pytest.raises(ValueError):
        parse_range("A1")


def test_to_a1_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(702, 0))


# Additional B§1 coverage
def test_parse_ref_a10000_rejected():
    with pytest.raises(ValueError):
        parse_ref("A10000")


def test_parse_ref_rejects_partial_match():
    with pytest.raises(ValueError):
        parse_ref("A1 ")


def test_parse_ref_column_extremes():
    assert parse_ref("A1") == Ref(0, 0, False, False)
    assert parse_ref("Z1") == Ref(25, 0, False, False)
    assert parse_ref("AA1") == Ref(26, 0, False, False)
    assert parse_ref("ZZ9999") == Ref(701, 9998, False, False)


def test_parse_range_single_cell_valid():
    assert parse_range("A1:A1") == (Ref(0, 0), Ref(0, 0))


def test_parse_range_tie_uses_first_corner():
    # col tie and row tie: each axis takes its flag from the first corner
    assert parse_range("A$1:$A1") == (Ref(0, 0, False, True), Ref(0, 0, False, True))


def test_parse_range_normalizes_order():
    assert parse_range("C3:A1") == (Ref(0, 0), Ref(2, 2))


def test_to_a1_plain_and_extremes():
    assert to_a1(Ref(0, 0)) == "A1"
    assert to_a1(Ref(701, 9998, True, True)) == "$ZZ$9999"


def test_to_a1_row_out_of_range():
    with pytest.raises(ValueError):
        to_a1(Ref(0, 9999))

